    <section class="rounded-2xl border bg-white p-5"><h2 class="text-xl font-bold">Activity & re-engagement</h2><div class="mt-4 grid gap-3 sm:grid-cols-3"><?php $__currentLoopData = [['Daily active',$report['active']['daily']],['Weekly active',$report['active']['weekly']],['Monthly active',$report['active']['monthly']]]; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $metric): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><p class="rounded-xl bg-slate-50 p-4 text-sm"><?php echo e($metric[0]); ?> <strong class="ml-2"><?php echo e($metric[1]); ?></strong></p><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div><p class="mt-4 text-sm">Currently inactive for at least 24h: <?php echo e($report['inactivity']->hours24??0); ?> · 48h: <?php echo e($report['inactivity']->hours48??0); ?> · 7 days: <?php echo e($report['inactivity']->days7??0); ?> · 14 days: <?php echo e($report['inactivity']->days14??0); ?>.</p><p class="mt-3 text-sm">Reminder opt-outs: <?php echo e($report['eventCounts']['unsubscribed']??0); ?>. Recorded returns: <?php echo e($report['eventCounts']['returned']??0); ?>.</p><div class="mt-3 flex flex-wrap gap-4"><?php $__currentLoopData = $report['returnChannels']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $row): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><p class="text-sm"><?php echo e(ucfirst($row->channel)); ?> delivery before return: <?php echo e($row->users); ?> users</p><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div><p class="mt-3 text-xs text-slate-500">Activity comes from real page visits and foreground actions. Polls, prefetches, permission checks and autosave requests are excluded. Returns after multiple channels may appear in more than one channel; this is observational attribution.</p></section>
