    <section class="rounded-2xl border bg-white p-5"><h2 class="text-xl font-bold">Delivery diagnostics</h2><p class="mt-3 text-sm">Mail transport: <strong><?php echo e($diagnostics['mail_driver']); ?></strong>. SMTP credentials: <?php echo e($diagnostics['smtp_credentials']?'present':'not configured'); ?>. VAPID keys: <?php echo e($diagnostics['push_configured']?'configured':'not configured'); ?>. Queue connection: <?php echo e($diagnostics['queue_driver']); ?>. Failed notification jobs: <?php echo e($diagnostics['notification_queue_failures']); ?>.</p><p class="mt-3 text-xs text-slate-500">Workers must consume the notifications queue. Unknown provider outcomes require reconciliation before retrying. HTTPS, browser permission, OS settings and valid subscriptions are required for live push.</p><div class="mt-4 space-y-3"><?php $__empty_1 = true; $__currentLoopData = $failures; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $failure): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><article class="flex flex-wrap items-center justify-between gap-3 rounded-xl border p-3"><div><p class="text-sm font-semibold"><?php echo e(ucfirst($failure->channel)); ?> · <?php echo e($failure->status); ?> · attempt <?php echo e($failure->attempt_count); ?></p><p class="mt-1 text-xs text-slate-500"><?php echo e(preg_match('/^[a-z_0-9]+(:[A-Za-z0-9_]+)?$/',(string)$failure->error_message)?$failure->error_message:'Legacy transport error; inspect restricted server logs.'); ?> · <?php echo e($failure->attempted_at?->format('Y-m-d H:i')); ?></p></div><?php if(in_array($failure->status,['failed','retrying'])&&$failure->attempt_count<5): ?><form method="POST" action="<?php echo e(route('admin.notifications.delivery.retry',$failure)); ?>"><?php echo csrf_field(); ?><button class="acad-secondary-button">Retry eligible delivery</button></form><?php endif; ?></article><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($_